module main_v5ec133 (
 input pix_clk,
 input rst_n,
 input [15:0] din,
 input empty_fifo,
 input sobel,
 input [7:0] threshold,
 output rd_en,
 output debug_led,
 output lcd_vs,
 output lcd_hs,
 output lcd_pclk,
 output lcd_de,
 output lcd_b0,
 output lcd_b1,
 output lcd_b2,
 output lcd_b3,
 output lcd_b4,
 output lcd_b5,
 output lcd_g0,
 output lcd_g1,
 output lcd_g2,
 output lcd_g3,
 output lcd_g4,
 output lcd_g5,
 output lcd_r0,
 output lcd_r1,
 output lcd_r2,
 output lcd_r3,
 output lcd_r4,
 output lcd_r5,
 output lcd_reset_n,
 output lcd_spi_cs_n,
 output lcd_spi_sck,
 output lcd_spi_dc,
 output lcd_spi_mosi,
 output lcd_im0
);
 // ============================================================
 // NHD-2.1-480480AF-ASXP SDRAM-to-TFT bridge
 // IceStudio code-block version
 //
 // Behavior:
 //   1. Hardware-reset and initialize the ST7701S over SPI.
 //   2. Show a local color test pattern for TEST_FRAMES frames.
 //   3. Switch at a frame boundary to the SDRAM/camera stream.
 //   4. Show MAGENTA if the SDRAM display FIFO is empty.
 //
 // Camera source: 640 x 480 RGB565
 // TFT output:    centered 480 x 480 RGB666 crop
 //
 // Inputs:
 //   pix_clk, rst_n, din[15:0], empty_fifo, sobel, threshold[7:0]
 //
 // Outputs:
 //   rd_en, debug_led
 //   lcd_vs, lcd_hs, lcd_pclk, lcd_de
 //   lcd_b0..lcd_b5, lcd_g0..lcd_g5, lcd_r0..lcd_r5
 //   lcd_reset_n, lcd_spi_cs_n, lcd_spi_sck,
 //   lcd_spi_dc, lcd_spi_mosi, lcd_im0
 // ============================================================
 
 
 // ============================================================
 // Display timing
 //
 // We use 640 clocks per line so all 640 source pixels can be
 // consumed once per camera row:
 //
 //   x =   0..79   read/discard left crop
 //   x =  80..559  read and display 480 pixels
 //   x = 560..639  read/discard right crop
 //
 // TFT active width remains 480 pixels. The extra horizontal
 // blanking gives a frame rate of about 55.6 Hz at 18 MHz.
 // ============================================================
 
 localparam H_TOTAL      = 640;
 localparam H_DE_START   = 80;
 localparam H_DE_END     = 560;
 localparam H_SYNC_START = 600;
 localparam H_SYNC_END   = 620;
 
 localparam V_TOTAL      = 506;
 localparam V_DE_START   = 0;
 localparam V_DE_END     = 480;
 localparam V_SYNC_START = 490;
 localparam V_SYNC_END   = 496;
 
 // Set to 1 to hold the local test pattern forever.
 // Set to 0 to show the test pattern first and then the camera.
 localparam FORCE_TEST_PATTERN = 1'b0;
 
 // Set to 1 to show the live Sobel magnitude as grayscale.
 // Set to 0 for thresholded black/white edges.
 localparam SOBEL_GRAYSCALE_DEBUG = 1'b0;
 
 // Number of complete TFT frames to show the local pattern.
 // 120 frames is a little over two seconds at ~55.6 Hz.
 localparam [7:0] TEST_FRAMES = 8'd120;
 
 
 // ============================================================
 // State shared by video timing and LCD initialization
 // ============================================================
 
 reg init_done = 1'b0;
 
 reg [9:0] x = 10'd0;
 reg [9:0] y = 10'd0;
 
 reg [7:0] test_frame_count = 8'd0;
 
 reg [5:0] r;
 reg [5:0] g;
 reg [5:0] b;
 
 
 // ============================================================
 // Video counters
 // Hold at zero until SPI initialization finishes.
 // ============================================================
 
 always @(posedge pix_clk or negedge rst_n) begin
     if (!rst_n) begin
         x <= 10'd0;
         y <= 10'd0;
     end
     else if (!init_done) begin
         x <= 10'd0;
         y <= 10'd0;
     end
     else if (x == H_TOTAL - 1) begin
         x <= 10'd0;
 
         if (y == V_TOTAL - 1)
             y <= 10'd0;
         else
             y <= y + 1'b1;
     end
     else begin
         x <= x + 1'b1;
     end
 end
 
 
 // Count complete frames so the transition from test pattern to
 // camera mode happens only at the beginning of a new frame.
 always @(posedge pix_clk or negedge rst_n) begin
     if (!rst_n) begin
         test_frame_count <= 8'd0;
     end
     else if (!init_done) begin
         test_frame_count <= 8'd0;
     end
     else if (!FORCE_TEST_PATTERN &&
              test_frame_count < TEST_FRAMES &&
              x == H_TOTAL - 1 &&
              y == V_TOTAL - 1) begin
         test_frame_count <= test_frame_count + 1'b1;
     end
 end
 
 wire test_mode;
 assign test_mode = FORCE_TEST_PATTERN ||
                    (test_frame_count < TEST_FRAMES);
 
 
 // ============================================================
 // TFT active area and camera FIFO consumption
 // ============================================================
 
 wire lcd_active_area;
 wire camera_source_row;
 wire consume_camera_pixel;
 
 assign lcd_active_area = init_done &&
                          (x >= H_DE_START) &&
                          (x <  H_DE_END) &&
                          (y >= V_DE_START) &&
                          (y <  V_DE_END);
 
 // During local test mode, leave the SDRAM display FIFO untouched.
 // In camera mode, consume all 640 pixels for every source row.
 assign camera_source_row = init_done &&
                            !test_mode &&
                            (y >= V_DE_START) &&
                            (y <  V_DE_END);
 
 assign consume_camera_pixel = camera_source_row &&
                               (x < H_TOTAL) &&
                               !empty_fifo;
 
 assign rd_en = consume_camera_pixel;
 
 
 // ============================================================
 // TFT timing outputs
 // ============================================================
 
 assign lcd_pclk = init_done ? ~pix_clk : 1'b0;
 
 assign lcd_hs = init_done ? ~((x >= H_SYNC_START) &&
                               (x <  H_SYNC_END)) : 1'b1;
 
 assign lcd_vs = init_done ? ~((y >= V_SYNC_START) &&
                               (y <  V_SYNC_END)) : 1'b1;
 
 // DE must describe the TFT's visible 480 x 480 area.
 // Do not gate DE with empty_fifo; otherwise FIFO underflow makes
 // the panel go completely black and hides useful diagnostics.
 assign lcd_de = lcd_active_area;
 
 
 // ============================================================
 // SDRAM RGB565 / Sobel conversion
 // ============================================================
 
 wire [5:0] cam_r6;
 wire [5:0] cam_g6;
 wire [5:0] cam_b6;
 wire edge_on;
 
 assign cam_r6 = {din[15:11], din[15]};
 assign cam_g6 = din[10:5];
 assign cam_b6 = {din[4:0], din[4]};
 
 assign edge_on = (din[7:0] > threshold);
 
 
 // ============================================================
 // Pixel selection
 //
 // Local test:
 //   Four bright quadrants.
 //
 // Camera mode:
 //   Center crop of the 640 x 480 SDRAM stream.
 //
 // Diagnostic:
 //   If camera mode is active but empty_fifo is high, show magenta.
 // ============================================================
 
 wire [9:0] visible_x;
 assign visible_x = x - H_DE_START;
 
 always @* begin
     r = 6'd0;
     g = 6'd0;
     b = 6'd0;
 
     if (lcd_active_area) begin
         if (test_mode) begin
             if (visible_x < 10'd240 && y < 10'd240) begin
                 r = 6'd63;
                 g = 6'd0;
                 b = 6'd0;
             end
             else if (visible_x >= 10'd240 && y < 10'd240) begin
                 r = 6'd0;
                 g = 6'd63;
                 b = 6'd0;
             end
             else if (visible_x < 10'd240 && y >= 10'd240) begin
                 r = 6'd0;
                 g = 6'd0;
                 b = 6'd63;
             end
             else begin
                 r = 6'd63;
                 g = 6'd63;
                 b = 6'd63;
             end
 
             // Black center crosshair.
             if (visible_x == 10'd240 || y == 10'd240) begin
                 r = 6'd0;
                 g = 6'd0;
                 b = 6'd0;
             end
         end
         else if (empty_fifo) begin
             // Magenta means TFT timing/init works but no SDRAM pixel
             // is available at this moment.
             r = 6'd63;
             g = 6'd0;
             b = 6'd63;
         end
         else if (sobel) begin
             if (SOBEL_GRAYSCALE_DEBUG) begin
                 // Live Sobel magnitude from SDRAM.
                 r = din[7:2];
                 g = din[7:2];
                 b = din[7:2];
             end
             else if (edge_on) begin
                 r = 6'd63;
                 g = 6'd63;
                 b = 6'd63;
             end
             else begin
                 r = 6'd0;
                 g = 6'd0;
                 b = 6'd0;
             end
         end
         else begin
             r = cam_r6;
             g = cam_g6;
             b = cam_b6;
         end
     end
 end
 
 
 // ============================================================
 // RGB666 outputs to LCD
 // ============================================================
 
 assign lcd_b0 = b[0];
 assign lcd_b1 = b[1];
 assign lcd_b2 = b[2];
 assign lcd_b3 = b[3];
 assign lcd_b4 = b[4];
 assign lcd_b5 = b[5];
 
 assign lcd_g0 = g[0];
 assign lcd_g1 = g[1];
 assign lcd_g2 = g[2];
 assign lcd_g3 = g[3];
 assign lcd_g4 = g[4];
 assign lcd_g5 = g[5];
 
 assign lcd_r0 = r[0];
 assign lcd_r1 = r[1];
 assign lcd_r2 = r[2];
 assign lcd_r3 = r[3];
 assign lcd_r4 = r[4];
 assign lcd_r5 = r[5];
 
 
 // RGB + 8-bit SPI mode: IM0=1, IM1=0, IM2=0.
 assign lcd_im0 = 1'b1;
 
 
 // ============================================================
 // SPI initialization constants
 // These are explicitly sized to avoid syntax errors from slicing
 // unsized parameters in Yosys/IceStudio.
 // ============================================================
 
 localparam [23:0] RESET_LOW_TICKS  = 24'd1800000;  // 100 ms at 18 MHz
 localparam [23:0] RESET_WAIT_TICKS = 24'd360000;   // 20 ms at 18 MHz
 localparam [23:0] DELAY_120MS      = 24'd2160000;  // 120 ms at 18 MHz
 localparam [23:0] DELAY_10MS       = 24'd180000;   // 10 ms at 18 MHz
 
 localparam [7:0] SPI_HALF_PERIOD   = 8'd7;         // SCK about 1.125 MHz
 localparam [7:0] INIT_LAST         = 8'd249;
 
 
 // ============================================================
 // Init table format:
 //
 // init_word[9]    = 0 for SPI byte, 1 for delay
 // init_word[8]    = DCX value for SPI byte: 0 command, 1 data
 // init_word[7:0]  = byte value, or delay code
 //
 // Delay codes:
 //   8'h01 = 120 ms
 //   8'h02 = 10 ms
 // ============================================================
 
 function [23:0] delay_ticks;
     input [7:0] code;
     begin
         case (code)
             8'h01: delay_ticks = DELAY_120MS;
             8'h02: delay_ticks = DELAY_10MS;
             default: delay_ticks = DELAY_10MS;
         endcase
     end
 endfunction
 
 function [9:0] init_word;
     input [7:0] idx;
     begin
         case (idx)
         8'd0: init_word = 10'h0FF;
         8'd1: init_word = 10'h177;
         8'd2: init_word = 10'h101;
         8'd3: init_word = 10'h100;
         8'd4: init_word = 10'h100;
         8'd5: init_word = 10'h113;
         8'd6: init_word = 10'h0EF;
         8'd7: init_word = 10'h108;
         8'd8: init_word = 10'h03A;
         8'd9: init_word = 10'h166;
         8'd10: init_word = 10'h0FF;
         8'd11: init_word = 10'h177;
         8'd12: init_word = 10'h101;
         8'd13: init_word = 10'h100;
         8'd14: init_word = 10'h100;
         8'd15: init_word = 10'h110;
         8'd16: init_word = 10'h0C0;
         8'd17: init_word = 10'h13B;
         8'd18: init_word = 10'h100;
         8'd19: init_word = 10'h0C1;
         8'd20: init_word = 10'h109;
         8'd21: init_word = 10'h105;
         8'd22: init_word = 10'h0C2;
         8'd23: init_word = 10'h107;
         8'd24: init_word = 10'h102;
         8'd25: init_word = 10'h0C6;
         8'd26: init_word = 10'h121;
         8'd27: init_word = 10'h0CC;
         8'd28: init_word = 10'h130;
         8'd29: init_word = 10'h0B0;
         8'd30: init_word = 10'h1C0;
         8'd31: init_word = 10'h154;
         8'd32: init_word = 10'h15C;
         8'd33: init_word = 10'h10D;
         8'd34: init_word = 10'h151;
         8'd35: init_word = 10'h106;
         8'd36: init_word = 10'h109;
         8'd37: init_word = 10'h108;
         8'd38: init_word = 10'h107;
         8'd39: init_word = 10'h124;
         8'd40: init_word = 10'h103;
         8'd41: init_word = 10'h111;
         8'd42: init_word = 10'h10F;
         8'd43: init_word = 10'h1AC;
         8'd44: init_word = 10'h1B5;
         8'd45: init_word = 10'h17F;
