         8'd248: init_word = 10'h036;
         8'd249: init_word = 10'h100;
         default: init_word = 10'h202;
         endcase
     end
 endfunction
 
 
 
 // ============================================================
 // SPI initialization FSM
 // ============================================================
 
 localparam S_RESET_LOW  = 4'd0;
 localparam S_RESET_WAIT = 4'd1;
 localparam S_LOAD       = 4'd2;
 localparam S_DECODE     = 4'd3;
 localparam S_DELAY      = 4'd4;
 localparam S_SPI_LOW    = 4'd5;
 localparam S_SPI_HIGH   = 4'd6;
 localparam S_NEXT       = 4'd7;
 localparam S_DONE       = 4'd8;
 
 reg [3:0] init_state = S_RESET_LOW;
 
 reg lcd_reset_n_reg = 1'b0;
 reg spi_cs_n_reg    = 1'b1;
 reg spi_sck_reg     = 1'b0;
 reg spi_dc_reg      = 1'b0;
 reg spi_mosi_reg    = 1'b0;
 
 reg [23:0] wait_count = 24'd0;
 reg [23:0] wait_limit = 24'd0;
 
 reg [7:0] init_index = 8'd0;
 reg [9:0] current_word = 10'd0;
 
 reg [7:0] send_byte = 8'd0;
 reg [2:0] bit_index = 3'd7;
 reg [7:0] spi_count = 8'd0;
 
 reg [25:0] heartbeat = 26'd0;
 
 always @(posedge pix_clk or negedge rst_n) begin
     if (!rst_n) begin
         init_state      <= S_RESET_LOW;
 
         lcd_reset_n_reg <= 1'b0;
         spi_cs_n_reg    <= 1'b1;
         spi_sck_reg     <= 1'b0;
         spi_dc_reg      <= 1'b0;
         spi_mosi_reg    <= 1'b0;
 
         init_done       <= 1'b0;
 
         wait_count      <= 24'd0;
         wait_limit      <= 24'd0;
         init_index      <= 8'd0;
         current_word    <= 10'd0;
         send_byte       <= 8'd0;
         bit_index       <= 3'd7;
         spi_count       <= 8'd0;
         heartbeat       <= 26'd0;
     end
     else begin
         heartbeat <= heartbeat + 1'b1;
 
         case (init_state)
 
             S_RESET_LOW: begin
                 lcd_reset_n_reg <= 1'b0;
                 spi_cs_n_reg    <= 1'b1;
                 spi_sck_reg     <= 1'b0;
                 spi_dc_reg      <= 1'b0;
                 spi_mosi_reg    <= 1'b0;
                 init_done       <= 1'b0;
 
                 if (wait_count >= RESET_LOW_TICKS) begin
                     wait_count <= 24'd0;
                     lcd_reset_n_reg <= 1'b1;
                     init_state <= S_RESET_WAIT;
                 end
                 else begin
                     wait_count <= wait_count + 1'b1;
                 end
             end
 
             S_RESET_WAIT: begin
                 lcd_reset_n_reg <= 1'b1;
 
                 if (wait_count >= RESET_WAIT_TICKS) begin
                     wait_count <= 24'd0;
                     init_index <= 8'd0;
                     init_state <= S_LOAD;
                 end
                 else begin
                     wait_count <= wait_count + 1'b1;
                 end
             end
 
             S_LOAD: begin
                 current_word <= init_word(init_index);
                 init_state   <= S_DECODE;
             end
 
             S_DECODE: begin
                 if (current_word[9]) begin
                     wait_count   <= 24'd0;
                     wait_limit   <= delay_ticks(current_word[7:0]);
                     spi_cs_n_reg <= 1'b1;
                     spi_sck_reg  <= 1'b0;
                     init_state   <= S_DELAY;
                 end
                 else begin
                     send_byte    <= current_word[7:0];
                     bit_index    <= 3'd7;
                     spi_count    <= 8'd0;
 
                     spi_cs_n_reg <= 1'b0;
                     spi_sck_reg  <= 1'b0;
                     spi_dc_reg   <= current_word[8];
                     spi_mosi_reg <= current_word[7];
 
                     init_state   <= S_SPI_LOW;
                 end
             end
 
             S_DELAY: begin
                 spi_cs_n_reg <= 1'b1;
                 spi_sck_reg  <= 1'b0;
 
                 if (wait_count >= wait_limit) begin
                     wait_count <= 24'd0;
                     init_state <= S_NEXT;
                 end
                 else begin
                     wait_count <= wait_count + 1'b1;
                 end
             end
 
             S_SPI_LOW: begin
                 spi_sck_reg  <= 1'b0;
                 spi_mosi_reg <= send_byte[bit_index];
 
                 if (spi_count >= SPI_HALF_PERIOD) begin
                     spi_count   <= 8'd0;
                     spi_sck_reg <= 1'b1;  // LCD samples on rising edge
                     init_state  <= S_SPI_HIGH;
                 end
                 else begin
                     spi_count <= spi_count + 1'b1;
                 end
             end
 
             S_SPI_HIGH: begin
                 spi_sck_reg <= 1'b1;
 
                 if (spi_count >= SPI_HALF_PERIOD) begin
                     spi_count   <= 8'd0;
                     spi_sck_reg <= 1'b0;
 
                     if (bit_index == 3'd0) begin
                         spi_cs_n_reg <= 1'b1;
                         init_state   <= S_NEXT;
                     end
                     else begin
                         bit_index  <= bit_index - 1'b1;
                         init_state <= S_SPI_LOW;
                     end
                 end
                 else begin
                     spi_count <= spi_count + 1'b1;
                 end
             end
 
             S_NEXT: begin
                 spi_cs_n_reg <= 1'b1;
                 spi_sck_reg  <= 1'b0;
 
                 if (init_index == INIT_LAST) begin
                     init_done  <= 1'b1;
                     init_state <= S_DONE;
                 end
                 else begin
                     init_index <= init_index + 1'b1;
                     init_state <= S_LOAD;
                 end
             end
 
             S_DONE: begin
                 init_done       <= 1'b1;
                 lcd_reset_n_reg <= 1'b1;
                 spi_cs_n_reg    <= 1'b1;
                 spi_sck_reg     <= 1'b0;
                 spi_dc_reg      <= 1'b1;
                 spi_mosi_reg    <= 1'b0;
             end
 
             default: begin
                 init_state <= S_RESET_LOW;
             end
 
         endcase
     end
 end
 
 assign lcd_reset_n   = lcd_reset_n_reg;
 assign lcd_spi_cs_n  = spi_cs_n_reg;
 assign lcd_spi_sck   = spi_sck_reg;
 assign lcd_spi_dc    = spi_dc_reg;
 assign lcd_spi_mosi  = spi_mosi_reg;
 
 // During init: LED shows SPI clock activity.
 // After init: LED blinks from heartbeat counter.
 assign debug_led = !init_done ? spi_sck_reg :
                    (test_mode ? heartbeat[23] :
                    (empty_fifo ? 1'b1 : heartbeat[22]));
 
endmodule

module main_v9df384 (
 input clkin,
 output clkout_18MHz,
 output locked
);
  // 32-bit phase accumulator
     reg [31:0] accumulator = 32'd0;
 
     always @(posedge clkin) begin
         // Add the calculated tuning word every clock cycle
         accumulator <= accumulator + 32'd3092376453;
     end
 
     // Use the Most Significant Bit (MSB) as the output clock
     assign clkout_18MHz = accumulator[31];
endmodule
